const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const quantities={stem:'Stem length',leaf:'Leaf spread',plants:'Number of plants'},units={mm:'mm',cm:'cm',plants:'plants'};
export function fieldChartArt(snapshot){
 const rows=snapshot.rows||[],values=snapshot.values||{},quantity=quantities[snapshot.quantity]||'Label not chosen',unit=units[snapshot.unit]||'unit not chosen';
 if(!rows.length)return '<div class="fn-empty-chart"><p>No rows selected yet.</p><p>Choose rows on the Data page.</p></div>';
 const label=`Your draft chart: ${quantity}, ${unit}. `+rows.map(({observation:r})=>`Model day ${r.day}, ${r.conditionLabel}, specimen ${r.specimen}: ${values[r.id]===null?'blank':values[r.id]+' '+unit}`).join('; ');
 const pending=rows.some(({observation:r})=>snapshot.pending&&snapshot.pending.bars[r.id]!==String(values[r.id]??''));
 return `<figure class="fn-chart"><figcaption><strong>Your draft chart</strong><span>${quantity} · ${unit}</span></figcaption><svg viewBox="0 0 460 245" role="img" aria-label="${esc(label)}"><rect x="0" y="0" width="460" height="245" fill="#fffcf2"/>${Array.from({length:8},(_,i)=>`<path d="M${60+i*5*10} 30V190" stroke="${i===0?'#405e50':'#d4ddca'}" stroke-width="${i===0?2:1}"/><text x="${60+i*50}" y="213" text-anchor="middle" fill="#183f39" font-size="16">${i*10}</text>`).join('')}<path d="M60 190H410" stroke="#405e50" stroke-width="2"/>${rows.map(({observation:r},i)=>{const value=values[r.id],y=58+i*78;return `<text x="60" y="${y-15}" fill="#183f39" font-size="16">Day ${r.day} · ${esc(r.conditionLabel)} · ${r.specimen}</text>${value===null?`<text x="70" y="${y+17}" fill="#775b28" font-size="16">Blank: no value entered</text>`:`${value===0?`<circle cx="60" cy="${y+10}" r="4" fill="#397958"/>`:`<rect x="60" y="${y}" width="${value*5}" height="28" rx="3" fill="#397958"/>`}<text x="${Math.min(430,70+value*5)}" y="${y+19}" fill="#183f39" font-size="16">${value}</text>`}`;}).join('')}<text x="235" y="237" text-anchor="middle" fill="#183f39" font-size="16">${esc(quantity)} (${esc(unit)}) · scale begins at 0</text></svg><p class="fn-pending-notice" ${pending?'':'hidden'}>Typed entries are waiting to be set. This picture still uses the last applied values.</p><p class="tiny">${esc(label)}. Bar values are your entries; the supplied model table stays separate.</p></figure>`;
}
